// UNVERIFIED: field names below (message_id / status / delivered) are a
// best guess pending a real Sendchamp DLR payload to inspect. Update once
// verified against a live webhook delivery.
const body = $json.body ?? $json;
const providerMessageId = body.message_id ?? body.data?.id ?? body.id ?? null;
const rawStatus = (body.status ?? body.data?.status ?? '').toString().toLowerCase();

let status = 'sent';
if (['delivered', 'success'].includes(rawStatus)) status = 'delivered';
if (['failed', 'undelivered', 'error'].includes(rawStatus)) status = 'failed';

return [{ json: { provider_message_id: providerMessageId, status } }];
